**Frontend Store:**
```typescript
// stores/patternStore.ts
import { create } from 'zustand';
import { devtools } from 'zustand/middleware';

interface Pattern {
  userId: string;
  timesheetDayOfWeek: number;
  preferredSubmissionTime: string;
  updatedAt: string;
}

interface PatternState {
  pattern: Pattern | null;
  isLoading: boolean;

  fetchPattern: (userId: string) => Promise<void>;
  savePattern: (pattern: Pattern) => Promise<void>;
}

export const usePatternStore = create<PatternState>()(
  devtools(
    (set) => ({
      pattern: null,
      isLoading: false,

      fetchPattern: async (userId) => {
        set({ isLoading: true });
        try {
          const response = await fetch(`/patterns/${userId}`, {
            headers: { Authorization: `Bearer ${getToken()}` }
          });

          if (response.ok) {
            const pattern = await response.json();
            set({ pattern, isLoading: false });
          } else {
            set({ isLoading: false });
          }
        } catch (error) {
          console.error('Failed to fetch pattern:', error);
          set({ isLoading: false });
        }
      },

      savePattern: async (pattern) => {
        set({ isLoading: true });
        try {
          const response = await fetch('/patterns', {
            method: 'POST',
            headers: { 
              'Content-Type': 'application/json',
              Authorization: `Bearer ${getToken()}`
            },
            body: JSON.stringify(pattern)
          });

          if (response.ok) {
            const saved = await response.json();
            set({ pattern: saved, isLoading: false });
          }
        } catch (error) {
          console.error('Failed to save pattern:', error);
          set({ isLoading: false });
        }
      },
    }),
    { name: 'pattern-store' }
  )
);
```

